package com.peiwan.platform.settlement;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.peiwan.platform.persistence.entity.*;import com.peiwan.platform.persistence.mapper.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class SettlementService{
 private final CommissionRuleMapper rules;private final PlayerAccountMapper accounts;private final PlayerEarningMapper earnings;private final WithdrawalRequestMapper withdrawals;private final PlayerAccountTransactionMapper transactions;private final SettlementDataMapper data;private final OrderMapper orders;private final OrderSettlementMapper settlements;private final OrderSettlementDetailMapper settlementDetails;private final PlatformLedgerMapper platformLedger;private final com.peiwan.platform.serviceexception.ServiceLiabilityService liabilities;
 public SettlementService(CommissionRuleMapper rules,PlayerAccountMapper accounts,PlayerEarningMapper earnings,WithdrawalRequestMapper withdrawals,PlayerAccountTransactionMapper transactions,SettlementDataMapper data,OrderMapper orders,OrderSettlementMapper settlements,OrderSettlementDetailMapper settlementDetails,PlatformLedgerMapper platformLedger,com.peiwan.platform.serviceexception.ServiceLiabilityService liabilities){this.rules=rules;this.accounts=accounts;this.earnings=earnings;this.withdrawals=withdrawals;this.transactions=transactions;this.data=data;this.orders=orders;this.settlements=settlements;this.settlementDetails=settlementDetails;this.platformLedger=platformLedger;this.liabilities=liabilities;}
 @Transactional public void settleOrder(long orderId){if(settlements.selectCount(new QueryWrapper<OrderSettlementEntity>().eq("order_id",orderId))>0){liabilities.settleTransferCompensations(orderId);return;}var order=orders.selectById(orderId);if(order==null||!"COMPLETED".equals(order.orderStatus)||order.paidAmount==null||order.paidAmount.signum()<=0)return;var members=data.completedMembers(orderId);if(members.isEmpty())throw new IllegalArgumentException("陪玩服务订单没有已完成成员，不能结算");var rule=requiredRule();BigDecimal rate=(BigDecimal)rule.get("commission_rate");BigDecimal platformAmount=order.paidAmount.multiply(rate).setScale(2,RoundingMode.HALF_UP);BigDecimal pool=order.paidAmount.subtract(platformAmount);var settlement=new OrderSettlementEntity();settlement.settlementNo=no("SET");settlement.orderId=orderId;settlement.orderAmount=order.paidAmount;settlement.platformAmount=platformAmount;settlement.distributableAmount=pool;settlement.settlementStatus="SETTLED";settlement.settledAt=LocalDateTime.now();try{settlements.insert(settlement);}catch(DuplicateKeyException ignored){liabilities.settleTransferCompensations(orderId);return;}var platformDetail=new OrderSettlementDetailEntity();platformDetail.settlementId=settlement.id;platformDetail.orderId=orderId;platformDetail.detailType="PLATFORM_COMMISSION";platformDetail.amount=platformAmount;platformDetail.calculationBase=order.paidAmount;platformDetail.rate=rate;platformDetail.remark="订单平台佣金";settlementDetails.insert(platformDetail);if(platformAmount.signum()>0){var ledger=new PlatformLedgerEntity();ledger.ledgerNo=no("PL");ledger.orderId=orderId;ledger.settlementDetailId=platformDetail.id;ledger.businessType="SERVICE_COMMISSION";ledger.direction="IN";ledger.amount=platformAmount;ledger.remark="陪玩服务订单平台佣金";platformLedger.insert(ledger);}BigDecimal allocated=BigDecimal.ZERO;BigDecimal equalShare=pool.divide(BigDecimal.valueOf(members.size()),2,RoundingMode.DOWN);for(int i=0;i<members.size();i++){var member=members.get(i);long memberId=((Number)member.get("id")).longValue(),playerId=((Number)member.get("player_id")).longValue();BigDecimal share=i==members.size()-1?pool.subtract(allocated):equalShare;allocated=allocated.add(share);var detail=new OrderSettlementDetailEntity();detail.settlementId=settlement.id;detail.orderId=orderId;detail.orderMemberId=memberId;detail.playerId=playerId;detail.detailType="PLAYER_INCOME";detail.amount=share;detail.calculationBase=pool;detail.rate=BigDecimal.ONE.divide(BigDecimal.valueOf(members.size()),4,RoundingMode.HALF_UP);detail.remark="完成成员平均分配";settlementDetails.insert(detail);var account=lockAccount(playerId);var earning=new PlayerEarningEntity();earning.earningNo=no("ERN");earning.orderId=orderId;earning.orderMemberId=memberId;earning.settlementDetailId=detail.id;earning.playerId=playerId;earning.orderAmount=order.paidAmount;earning.commissionRate=rate;earning.commissionAmount=platformAmount.divide(BigDecimal.valueOf(members.size()),2,RoundingMode.HALF_UP);earning.playerAmount=share;earning.earningStatus="AVAILABLE";earning.settledAt=settlement.settledAt;earnings.insert(earning);data.creditIncome(account.id,share);addTx(account,playerId,"AVAILABLE","IN","ORDER_INCOME",earning.earningNo,share,account.availableBalance,account.availableBalance.add(share),"多人订单完成收入");}liabilities.settleTransferCompensations(orderId);}
 public Map<String,Object> summary(long uid){long player=player(uid);var a=account(player);var rule=requiredRule();return map("account",accountView(a),"commissionRate",rule.get("commission_rate"),"playerRate",BigDecimal.ONE.subtract((BigDecimal)rule.get("commission_rate")),"minWithdrawAmount",rule.get("min_withdraw_amount"),"withdrawWeekday",rule.get("withdraw_weekday"),"canWithdrawToday",LocalDate.now().getDayOfWeek().getValue()==((Number)rule.get("withdraw_weekday")).intValue());}
 public Map<String,Object> earnings(long uid,int current,int size){long player=player(uid);current=Math.max(1,current);size=Math.min(100,Math.max(1,size));var page=data.playerEarnings(new Page<>(current,size),player);return map("records",page.getRecords().stream().map(this::camelRow).toList(),"current",current,"size",size,"total",page.getTotal());}
 public Map<String,Object> ownWithdrawals(long uid,int current,int size){long player=player(uid);current=Math.max(1,current);size=Math.min(100,Math.max(1,size));var page=withdrawals.selectPage(new Page<>(current,size),new QueryWrapper<WithdrawalRequestEntity>().eq("player_id",player).orderByDesc("id"));return map("records",page.getRecords(),"current",current,"size",size,"total",page.getTotal());}
 @Transactional public long withdraw(long uid,WithdrawCommand c){long player=player(uid);var rule=requiredRule();if(LocalDate.now().getDayOfWeek().getValue()!=((Number)rule.get("withdraw_weekday")).intValue())throw new IllegalArgumentException("仅每周一可以申请提现");BigDecimal minimum=(BigDecimal)rule.get("min_withdraw_amount");if(c.amount()==null||c.amount().compareTo(minimum)<0)throw new IllegalArgumentException("单次提现金额不能低于"+minimum.stripTrailingZeros().toPlainString()+"元");if(c.payoutMethod()==null||c.payoutMethod().isBlank()||c.accountName()==null||c.accountName().isBlank()||c.accountNo()==null||c.accountNo().isBlank())throw new IllegalArgumentException("请完整填写收款信息");var a=lockAccount(player);if(data.freeze(a.id,c.amount())!=1)throw new IllegalArgumentException("可提现余额不足");var w=new WithdrawalRequestEntity();w.withdrawalNo=no("WD");w.playerId=player;w.amount=c.amount();w.payoutMethod=c.payoutMethod();w.accountName=c.accountName();w.accountNo=c.accountNo();w.withdrawalStatus="PENDING";withdrawals.insert(w);addTx(a,player,"AVAILABLE","OUT","WITHDRAW_FREEZE",w.withdrawalNo,c.amount(),a.availableBalance,a.availableBalance.subtract(c.amount()),"申请提现冻结");addTx(a,player,"FROZEN","IN","WITHDRAW_FREEZE",w.withdrawalNo,c.amount(),a.frozenBalance,a.frozenBalance.add(c.amount()),"提现金额转入冻结");return w.id;}
 public Map<String,Object> adminList(int current,int size,String status){current=Math.max(1,current);size=Math.min(100,Math.max(1,size));var p=data.withdrawals(new Page<>(current,size),status);return map("records",p.getRecords(),"current",current,"size",size,"total",p.getTotal());}
 @Transactional public void audit(long id,String action,String remark,long operator){var w=withdrawals.selectById(id);if(w==null)throw new IllegalArgumentException("提现申请不存在");if(!"PENDING".equals(w.withdrawalStatus))throw new IllegalArgumentException("提现申请已处理");if(!Set.of("APPROVE","REJECT").contains(action))throw new IllegalArgumentException("审核动作无效");var a=lockAccount(w.playerId);if("APPROVE".equals(action)){if(data.approve(a.id,w.amount)!=1)throw new IllegalArgumentException("冻结余额异常");w.withdrawalStatus="PAID";addTx(a,w.playerId,"FROZEN","OUT","WITHDRAW_PAID",w.withdrawalNo,w.amount,a.frozenBalance,a.frozenBalance.subtract(w.amount),"提现审核通过并打款");}else{if(remark==null||remark.isBlank())throw new IllegalArgumentException("驳回必须填写原因");if(data.reject(a.id,w.amount)!=1)throw new IllegalArgumentException("冻结余额异常");w.withdrawalStatus="REJECTED";addTx(a,w.playerId,"FROZEN","OUT","WITHDRAW_REJECT",w.withdrawalNo,w.amount,a.frozenBalance,a.frozenBalance.subtract(w.amount),"提现驳回解除冻结");addTx(a,w.playerId,"AVAILABLE","IN","WITHDRAW_REJECT",w.withdrawalNo,w.amount,a.availableBalance,a.availableBalance.add(w.amount),"提现驳回退回余额");}w.reviewRemark=remark;w.reviewedBy=operator;w.reviewedAt=LocalDateTime.now();w.updatedAt=LocalDateTime.now();withdrawals.updateById(w);}
 public Map<String,Object> adminRule(){return requiredRule();}
 @Transactional public void updateRule(RuleCommand c){if(c.commissionRate()==null||c.commissionRate().signum()<0||c.commissionRate().compareTo(BigDecimal.ONE)>=0)throw new IllegalArgumentException("抽佣比例必须大于等于0且小于1");if(c.minWithdrawAmount()==null||c.minWithdrawAmount().signum()<=0)throw new IllegalArgumentException("最低提现金额必须大于0");if(c.withdrawWeekday()<1||c.withdrawWeekday()>7)throw new IllegalArgumentException("提现星期必须在1到7之间");var rule=rules.selectOne(new QueryWrapper<CommissionRuleEntity>().eq("enabled",true).orderByAsc("id").last("limit 1"));if(rule==null)throw new IllegalArgumentException("未配置启用的抽佣规则");rule.commissionRate=c.commissionRate();rule.minWithdrawAmount=c.minWithdrawAmount();rule.withdrawWeekday=c.withdrawWeekday();rule.updatedAt=LocalDateTime.now();rules.updateById(rule);}
 public byte[] export(String type){List<Map<String,Object>> rows;if("withdrawal".equals(type))rows=data.withdrawalReport();else if("earning".equals(type))rows=data.earningReport();else throw new IllegalArgumentException("报表类型无效");StringBuilder s=new StringBuilder("\uFEFF");if("withdrawal".equals(type)){s.append("提现单号,陪玩师编号,昵称,金额,状态,收款方式,收款人,收款账号,申请时间,审核时间,审核备注\r\n");for(var r:rows)s.append(csv(r.get("withdrawal_no"))).append(',').append(csv(r.get("player_no"))).append(',').append(csv(r.get("nickname"))).append(',').append(csv(r.get("amount"))).append(',').append(csv(r.get("withdrawal_status"))).append(',').append(csv(r.get("payout_method"))).append(',').append(csv(r.get("account_name"))).append(',').append(csv(r.get("account_no"))).append(',').append(csv(r.get("created_at"))).append(',').append(csv(r.get("reviewed_at"))).append(',').append(csv(r.get("review_remark"))).append("\r\n");}else{s.append("收入单号,订单号,陪玩师编号,昵称,订单金额,抽佣比例,平台佣金,陪玩师收入,状态,结算时间\r\n");for(var r:rows)s.append(csv(r.get("earning_no"))).append(',').append(csv(r.get("order_no"))).append(',').append(csv(r.get("player_no"))).append(',').append(csv(r.get("nickname"))).append(',').append(csv(r.get("order_amount"))).append(',').append(csv(r.get("commission_rate"))).append(',').append(csv(r.get("commission_amount"))).append(',').append(csv(r.get("player_amount"))).append(',').append(csv(r.get("earning_status"))).append(',').append(csv(r.get("settled_at"))).append("\r\n");}return s.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 private long player(long uid){Long id=data.playerId(uid);if(id==null)throw new IllegalArgumentException("当前账号尚未绑定可用陪玩师");return id;}private Map<String,Object> requiredRule(){var r=data.rule();if(r==null)throw new IllegalArgumentException("未配置启用的抽佣规则");return r;}private PlayerAccountEntity account(long player){var a=accounts.selectOne(new QueryWrapper<PlayerAccountEntity>().eq("player_id",player));return a==null?createAccount(player):a;}private PlayerAccountEntity lockAccount(long player){account(player);var r=data.lockAccount(player);var a=new PlayerAccountEntity();a.id=((Number)r.get("id")).longValue();a.playerId=player;a.availableBalance=(BigDecimal)r.get("available_balance");a.frozenBalance=(BigDecimal)r.get("frozen_balance");a.totalIncome=(BigDecimal)r.get("total_income");a.totalWithdrawn=(BigDecimal)r.get("total_withdrawn");return a;}private PlayerAccountEntity createAccount(long player){try{var a=new PlayerAccountEntity();a.playerId=player;a.availableBalance=BigDecimal.ZERO;a.frozenBalance=BigDecimal.ZERO;a.totalIncome=BigDecimal.ZERO;a.totalWithdrawn=BigDecimal.ZERO;a.version=0L;accounts.insert(a);return a;}catch(DuplicateKeyException e){return accounts.selectOne(new QueryWrapper<PlayerAccountEntity>().eq("player_id",player));}}private void addTx(PlayerAccountEntity a,long player,String balance,String direction,String type,String businessNo,BigDecimal amount,BigDecimal before,BigDecimal after,String remark){var t=new PlayerAccountTransactionEntity();t.transactionNo=no("ST");t.accountId=a.id;t.playerId=player;t.balanceType=balance;t.direction=direction;t.businessType=type;t.businessNo=businessNo;t.amount=amount;t.balanceBefore=before;t.balanceAfter=after;t.remark=remark;transactions.insert(t);}private String no(String p){return p+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+UUID.randomUUID().toString().replace("-","").substring(0,6).toUpperCase();}private String csv(Object v){String x=Objects.toString(v,"").replace("\"","\"\"");return "\""+x+"\"";}private Map<String,Object> accountView(PlayerAccountEntity a){return map("availableBalance",a.availableBalance,"frozenBalance",a.frozenBalance,"totalIncome",a.totalIncome,"totalWithdrawn",a.totalWithdrawn);}private Map<String,Object> map(Object...v){var m=new LinkedHashMap<String,Object>();for(int i=0;i<v.length;i+=2)m.put((String)v[i],v[i+1]);return m;}private Map<String,Object> camelRow(Map<String,Object> row){var result=new LinkedHashMap<String,Object>();for(var entry:row.entrySet()){var key=new StringBuilder();boolean upper=false;for(char c:entry.getKey().toCharArray()){if(c=='_'){upper=true;continue;}key.append(upper?Character.toUpperCase(c):c);upper=false;}result.put(key.toString(),entry.getValue());}return result;}public record WithdrawCommand(BigDecimal amount,String payoutMethod,String accountName,String accountNo){}public record RuleCommand(BigDecimal commissionRate,BigDecimal minWithdrawAmount,int withdrawWeekday){}
}
